import { Me } from "@/types/me.types";
import { BasePlaytomicClient } from "./base";
import { User } from "@/types/user.types";

export class PlaytomicClient extends BasePlaytomicClient {
  /**
   * retreives the current user object
   * @returns
   */
  public async getMe(): Promise<Me> {
    try {
      const response = await this.authInstance.get("/v2/users/me");
      if (!response.data) throw new Error("failed to get me");
      return response.data;
    } catch (e: any) {
      console.error(e);
      throw new Error("failed to get profile");
    }
  }

  /**
   * upserts the current client user
   */
  public async updateMe(me: Partial<Me>): Promise<Me> {
    try {
      const response = await this.authInstance.patch("/v2/users/me", me);
      if (!response.data) throw new Error("me not found");
      return response.data;
    } catch (e: any) {
      throw new Error("failed to get me");
    }
  }

  /**
   * gets a user by their id
   */
  public async getUser(id: string): Promise<User | null> {
    try {
      const response = await this.authInstance.get(`/v2/users/${id}`);
      if (!response.data) return null;
      return response.data;
    } catch (e: any) {
      throw new Error("failed to get user");
    }
  }
}
